<template><section class="wrap"><FmStatePanel v-if="loading" state="loading"/><FmStatePanel v-else-if="error" state="error" :description="error"/><FmStatePanel v-else-if="!rows.length" state="empty" :title="emptyText"/><template v-else><div class="desktop"><table><thead><tr><th v-for="c in columns" :key="c.key">{{c.label}}</th><th v-if="$slots.actions">操作</th></tr></thead><tbody><tr v-for="(row,i) in rows" :key="row[rowKey]??i"><td v-for="c in columns" :key="c.key"><slot :name="`cell-${c.key}`" :row="row" :value="row[c.key]">{{format(row,c)}}</slot></td><td v-if="$slots.actions"><div class="actions"><slot name="actions" :row="row"/></div></td></tr></tbody></table></div><div class="mobile"><article v-for="(row,i) in rows" :key="row[rowKey]??i"><dl><div v-for="c in columns" :key="c.key"><dt>{{c.label}}</dt><dd><slot :name="`cell-${c.key}`" :row="row" :value="row[c.key]">{{format(row,c)}}</slot></dd></div></dl><div v-if="$slots.actions" class="card-actions"><slot name="actions" :row="row"/></div></article></div></template></section></template>
<script setup>import FmStatePanel from"./FmStatePanel.vue";defineProps({columns:Array,rows:{type:Array,default:()=>[]},rowKey:{default:"id"},loading:Boolean,error:String,emptyText:{default:"暂无数据"}});function format(row,c){const v=row[c.key];return c.format?c.format(v,row):(v===null||v===undefined||v===""?"—":String(v))}</script>
<style scoped>.wrap{overflow:hidden;border:1px solid var(--fm-line);border-radius:14px;background:var(--fm-bg-card)}.desktop{overflow-x:auto}table{width:100%;min-width:720px;border-collapse:collapse}th{padding:11px 16px;border-bottom:1px solid var(--fm-line-soft);background:var(--fm-bg-warm);color:var(--fm-ink-muted);font-size:10px;letter-spacing:.08em;text-align:left;text-transform:uppercase}td{padding:13px 16px;border-bottom:1px solid var(--fm-line-soft);color:var(--fm-ink-soft);font-size:13px}tbody tr:last-child td{border:0}.actions{display:flex;justify-content:flex-end;gap:6px}.mobile{display:none}@media(max-width:720px){.wrap{border:0;background:transparent}.desktop{display:none}.mobile{display:grid;gap:10px}.mobile article{padding:16px;border:1px solid var(--fm-line);border-radius:12px;background:var(--fm-bg-card)}dl{display:grid;gap:10px;margin:0}dl div{display:grid;grid-template-columns:minmax(90px,.7fr) minmax(0,1.3fr);gap:12px}dt{color:var(--fm-ink-muted);font-size:10px;text-transform:uppercase}dd{min-width:0;margin:0;overflow-wrap:anywhere;text-align:right;font-size:13px}.card-actions{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:14px;padding-top:14px;border-top:1px solid var(--fm-line-soft)}}@media(max-width:420px){dl div{grid-template-columns:1fr;gap:3px}dd{text-align:left}.card-actions{grid-template-columns:1fr}}</style>
